"use client"

import { useState, useEffect } from "react"
import axios from "axios"
import { useNavigate } from "react-router-dom"
import {
  Users,
  Calendar,
  Package,
  DollarSign,
  FileText,
  TrendingUp,
  AlertCircle,
  Loader2,
  Clock,
  ChevronRight,
  ChevronDown,
  ChevronUp,
  ArrowUpRight, // Added for "Voir tous" button
} from "lucide-react"
import Layout from "./Layout"

// Import Chart.js
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  ArcElement,
  Title,
  Tooltip,
  Legend,
} from "chart.js"
import { Bar, Doughnut } from "react-chartjs-2"

// Register Chart.js components
ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, ArcElement, Title, Tooltip, Legend)

// Stats Card Component
function DashboardStatsCard({ icon, title, value, bgColor, textColor }) {
  return (
    <div className="bg-white rounded-xl shadow-md p-3 sm:p-4 border border-[#C8A45D/30]/50 flex items-center">
      <div
        className={`h-10 w-10 sm:h-12 sm:w-12 rounded-full ${bgColor} flex items-center justify-center mr-3 sm:mr-4`}
      >
        {icon}
      </div>
      <div>
        <p className="text-xs sm:text-sm text-gray-500">{title}</p>
        <p className={`text-lg sm:text-2xl font-bold ${textColor}`}>{value}</p>
      </div>
    </div>
  )
}

// Section Component
function DashboardSection({ title, icon, children, defaultExpanded = false }) {
  const [isExpanded, setIsExpanded] = useState(defaultExpanded)

  return (
    <div className="bg-white rounded-xl shadow-md border border-[#C8A45D/30]/50 overflow-hidden">
      <div
        className="bg-[#F5F6FA] p-3 sm:p-4 flex justify-between items-center cursor-pointer"
        onClick={() => setIsExpanded(!isExpanded)}
      >
        <div className="flex items-center gap-2">
          {icon}
          <h2 className="text-base sm:text-lg font-semibold text-[#00717F]">{title}</h2>
        </div>
        {isExpanded ? (
          <ChevronUp className="h-4 w-4 sm:h-5 sm:w-5 text-[#00717F]" />
        ) : (
          <ChevronDown className="h-4 w-4 sm:h-5 sm:w-5 text-[#00717F]" />
        )}
      </div>
      {isExpanded && <div className="p-3 sm:p-4">{children}</div>}
    </div>
  )
}

// Action Button Component
function DashboardActionButton({ icon, label, bgColor, onClick }) {
  return (
    <button
      onClick={onClick}
      className={`flex flex-col items-center justify-center p-2 sm:p-3 ${bgColor} rounded-lg hover:bg-opacity-80 transition-colors`}
    >
      <div className="mb-1 sm:mb-2">{icon}</div>
      <span className="text-xs font-medium text-gray-700">{label}</span>
    </button>
  )
}

// Main Dashboard Component
export default function DeputyDirectorDashboard() {
  const navigate = useNavigate()
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState("")
  const [dashboardData, setDashboardData] = useState({
    interns: { total: 0, active: 0, recent: [] },
    absences: { pending: 0, approved: 0, rejected: 0, recent: [] },
    inventory: { products: 0, lowStock: 0, expired: 0, recent: [] },
    payments: { total: 0, pending: 0, completed: 0, academicYear: "", paymentsByMonth: [], recent: [] },
    reports: { total: 0, recent: [] },
    consumption: { totalConsumption: 0, academicYear: "" },
  })
  const [timeRange, setTimeRange] = useState("week")

  useEffect(() => {
    fetchDashboardData()
  }, [timeRange])

  const fetchDashboardData = async () => {
    setIsLoading(true)
    setError("")
    const token = localStorage.getItem("token")

    if (!token) {
      setError("Authentication required. Please log in.")
      setIsLoading(false)
      return
    }

    try {
      const [internsRes, absencesRes, inventoryRes, paymentsRes, reportsRes, consumptionRes, totalPaymentsRes] =
        await Promise.all([
          axios.get(`${process.env.REACT_APP_API_URL}/api/interns`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Deputydirector" },
          }),
          axios.get(`${process.env.REACT_APP_API_URL}/api/absence/pending`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Deputydirector" },
          }),
          axios.get(`${process.env.REACT_APP_API_URL}/api/products`, {
            headers: { Authorization: `Bearer ${token}` },
          }),
          axios.get(`${process.env.REACT_APP_API_URL}/api/payments`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Deputydirector" },
          }),
          axios.get(`${process.env.REACT_APP_API_URL}/api/reports/my-reports`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Deputydirector" },
          }),
          axios.get(`${process.env.REACT_APP_API_URL}/api/interns/totalConsumption`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Deputydirector" },
          }),
          axios.get(`${process.env.REACT_APP_API_URL}/api/payments/total`, {
            headers: { Authorization: `Bearer ${token}`, Role: "Deputydirector" },
          }),
        ])

      const internsData = internsRes.data.data || []
      const recentInterns = internsData
        .filter((intern) => intern && intern.First_Name && intern.Last_Name)
        .slice(0, 5)
        .map((intern) => ({
          id: intern._id,
          name: `${intern.First_Name} ${intern.Last_Name}`,
          cff: intern.CFF,
          sector: intern.Sector,
          date: new Date(intern.createdAt).toLocaleDateString("fr-FR"),
        }))

      const absencesData = absencesRes.data.data || []
      const recentAbsences = absencesData.slice(0, 5).map((absence) => ({
        id: absence._id,
        internName: absence.stagerName,
        startDate: new Date(absence.startDate).toLocaleDateString("fr-FR"),
        endDate: new Date(absence.endDate).toLocaleDateString("fr-FR"),
        status: absence.status,
        reason: absence.reason,
      }))

      const inventoryData = inventoryRes.data || []
      const lowStockProducts = inventoryData.filter((product) => product.quantity < 50)
      const expiredProducts = inventoryData.filter((product) => {
        const expiryDate = new Date(product.expirationDate)
        const today = new Date()
        return expiryDate < today
      })
      const recentProducts = inventoryData.slice(0, 5).map((product) => ({
        id: product._id,
        name: product.nameProduct,
        quantity: product.quantity,
        price: product.priceForOne,
        expiryDate: new Date(product.expirationDate).toLocaleDateString("fr-FR"),
      }))

      const paymentsData = paymentsRes.data.data || []
      const completedPayments = paymentsData.filter((payment) => {
        const paidMonths = Object.keys(payment.payments).filter((month) => payment.payments[month] > 0).length
        const totalMonths = 12
        return paidMonths === totalMonths
      })
      const recentPayments = paymentsData
        .filter((payment) => payment && payment.internId && payment.internId.First_Name && payment.internId.Last_Name)
        .slice(0, 5)
        .map((payment) => ({
          id: payment._id,
          internName: `${payment.internId.First_Name} ${payment.internId.Last_Name}`,
          cff: payment.internId.CFF,
          amount: payment.totalAmount,
          date: new Date(payment.updatedAt).toLocaleDateString("fr-FR"),
        }))

      const consumptionStats = consumptionRes.data.success
        ? consumptionRes.data.data
        : { totalConsumption: 0, academicYear: "" }

      const totalPaymentsStats = totalPaymentsRes.data.success
        ? totalPaymentsRes.data.data
        : {
            totalAmount: 0,
            academicYear: "",
            monthlyBreakdown: {
              September: 0,
              October: 0,
              November: 0,
              December: 0,
              January: 0,
              February: 0,
              March: 0,
              April: 0,
              May: 0,
              June: 0,
              July: 0,
              August: 0,
            },
          }
      const paymentsByMonth = [
        totalPaymentsStats.monthlyBreakdown.September,
        totalPaymentsStats.monthlyBreakdown.October,
        totalPaymentsStats.monthlyBreakdown.November,
        totalPaymentsStats.monthlyBreakdown.December,
        totalPaymentsStats.monthlyBreakdown.January,
        totalPaymentsStats.monthlyBreakdown.February,
        totalPaymentsStats.monthlyBreakdown.March,
        totalPaymentsStats.monthlyBreakdown.April,
        totalPaymentsStats.monthlyBreakdown.May,
        totalPaymentsStats.monthlyBreakdown.June,
        totalPaymentsStats.monthlyBreakdown.July,
        totalPaymentsStats.monthlyBreakdown.August,
      ]

      const reportsData = reportsRes.data.data || []
      const recentReports = reportsData.slice(0, 5).map((report) => ({
        id: report._id,
        type: report.reportType,
        description: report.description,
        date: new Date(report.createdAt).toLocaleDateString("fr-FR"),
      }))

      setDashboardData({
        interns: { total: internsData.length, active: internsData.length, recent: recentInterns },
        absences: {
          pending: absencesData.filter((a) => a.status === "pending").length,
          approved: absencesData.filter((a) => a.status === "approved").length,
          rejected: absencesData.filter((a) => a.status === "rejected").length,
          recent: recentAbsences,
        },
        inventory: {
          products: inventoryData.length,
          lowStock: lowStockProducts.length,
          expired: expiredProducts.length,
          recent: recentProducts,
        },
        payments: {
          total: totalPaymentsStats.totalAmount,
          pending: paymentsData.length - completedPayments.length,
          completed: completedPayments.length,
          academicYear: totalPaymentsStats.academicYear,
          paymentsByMonth: paymentsByMonth,
          recent: recentPayments,
        },
        reports: { total: reportsData.length, recent: recentReports },
        consumption: {
          totalConsumption: consumptionStats.totalConsumption,
          academicYear: consumptionStats.academicYear,
        },
      })
    } catch (err) {
      console.error("Dashboard data fetch error:", err)
      setError(`Error fetching dashboard data: ${err.response?.data?.message || err.message}`)
    } finally {
      setIsLoading(false)
    }
  }

  const internsBySectorData = {
    labels: ["Cuisine", "Service", "Réception", "Housekeeping", "Administration"],
    datasets: [
      {
        label: "Nombre de stagiaires",
        data: [12, 19, 8, 15, 7],
        backgroundColor: [
          "rgba(0, 113, 127, 0.8)",
          "rgba(0, 113, 127, 0.6)",
          "rgba(200, 164, 93, 0.8)",
          "rgba(200, 164, 93, 0.6)",
          "rgba(0, 113, 127, 0.4)",
        ],
        borderColor: [
          "rgba(0, 113, 127, 1)",
          "rgba(0, 113, 127, 0.8)",
          "rgba(200, 164, 93, 1)",
          "rgba(200, 164, 93, 0.8)",
          "rgba(0, 113, 127, 0.6)",
        ],
        borderWidth: 1,
      },
    ],
  }

  const inventoryStatusData = {
    labels: ["Stock suffisant", "Stock faible", "Expiré"],
    datasets: [
      {
        data: [
          dashboardData.inventory.products - dashboardData.inventory.lowStock - dashboardData.inventory.expired,
          dashboardData.inventory.lowStock,
          dashboardData.inventory.expired,
        ],
        backgroundColor: ["rgba(0, 113, 127, 0.6)", "rgba(200, 164, 93, 0.6)", "rgba(255, 99, 132, 0.6)"],
        borderColor: ["rgba(0, 113, 127, 1)", "rgba(200, 164, 93, 1)", "rgba(255, 99, 132, 1)"],
        borderWidth: 1,
      },
    ],
  }

  const absenceRequestsData = {
    labels: ["En attente", "Approuvées", "Rejetées"],
    datasets: [
      {
        label: "Demandes d'absence",
        data: [dashboardData.absences.pending, dashboardData.absences.approved, dashboardData.absences.rejected],
        backgroundColor: ["rgba(0, 113, 127, 0.6)", "rgba(200, 164, 93, 0.6)", "rgba(255, 99, 132, 0.6)"],
        borderWidth: 0,
      },
    ],
  }

  return (
    <Layout>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 sm:py-6">
        {error && (
          <div className="mb-4 sm:mb-6 p-3 sm:p-4 bg-red-50 border-l-4 border-red-500 flex items-center gap-2 sm:gap-3 rounded-md">
            <AlertCircle className="h-4 w-4 sm:h-5 sm:w-5 text-red-500 flex-shrink-0" />
            <p className="text-xs sm:text-sm text-red-700">{error}</p>
          </div>
        )}

        {isLoading ? (
          <div className="flex justify-center items-center h-48 sm:h-64">
            <div className="flex flex-col items-center gap-2">
              <Loader2 className="h-8 w-8 sm:h-10 sm:w-10 text-[#00717F] animate-spin" />
              <p className="text-gray-500 text-xs sm:text-sm">Chargement des données...</p>
            </div>
          </div>
        ) : (
          <>
            <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] rounded-xl p-4 sm:p-6 text-white shadow-lg mb-6">
              <h1 className="text-xl sm:text-2xl font-bold">Bienvenue, Gestionnaire d'hôtel</h1>
              <p className="mt-1 text-white/80 text-xs sm:text-sm">
                Voici un aperçu de votre activité à l'Hôtel Pédagogique ISTA Benguérir
              </p>
