                    <Package className="h-4 w-4 sm:h-6 sm:w-6 text-white" />
                  </div>
                  <div>
                    <p className="text-white/70 text-xs sm:text-sm">Produits</p>
                    <p className="text-xl sm:text-2xl font-bold">{dashboardData.inventory.products}</p>
                  </div>
                </div>
              </div>
