                    <div className="flex items-center text-xs sm:text-sm text-[#00717F] font-medium">
                      <TrendingUp className="h-3 w-3 sm:h-4 sm:w-4 mr-1" />
                      <span>Total: {dashboardData.payments.total.toLocaleString()} DH</span>
                    </div>
                  </div>
                  <div className="h-48 sm:h-64 w-full relative overflow-x-auto">
                    <div className="flex h-full items-end justify-around min-w-[600px]">
                      {dashboardData.payments.paymentsByMonth.map((amount, index) => {
                        const isPositive = amount > 0

                        return (
                          <div key={index} className="flex flex-col items-center w-12 sm:w-16">
                            <div className="text-[10px] sm:text-xs font-medium text-[#00717F] mb-1">
                              {amount > 0 ? `${amount.toLocaleString()} DH` : ""}
                            </div>
                            <div className="relative w-8 sm:w-12 flex flex-col justify-end">
                              <div
                                className={`w-8 sm:w-12 rounded-sm ${isPositive ? "bg-[#00717F]" : "bg-gray-300"}`}
                                style={{
                                  height: `${Math.max((amount / 2400) * 190, 0)}px`,
                                }}
                              ></div>
                            </div>
                            <div className="text-[10px] sm:text-xs text-gray-500 mt-2 sm:mt-4">
                              {["Sep", "Oct", "Nov", "Déc", "Jan", "Fév", "Mar", "Avr", "Mai", "Juin", "Juil", "Aoû"][
                                index
                              ]}
                            </div>
                          </div>
                        )
                      })}
                    </div>
                    <div className="absolute inset-0 pointer-events-none">
                      {[600, 1200, 1800, 2400].map((value) => (
                        <div
                          key={value}
                          className="absolute w-full border-t border-gray-200 border-dashed"
                          style={{ bottom: `${(value / 2400) * 100}%` }}
                        >
                          <span className="absolute -left-8 sm:-left-12 text-[10px] sm:text-xs text-gray-500">
                            {value.toLocaleString()} DH
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
