                      <h3 className="text-xs sm:text-sm font-medium text-gray-500">Paiements récents</h3>
                      <button
                        onClick={() => navigate("/PaymentTracking")}
                        className="text-[10px] sm:text-xs text-[#00717F] hover:text-[#C8A45D] flex items-center gap-1"
