                      </button>
                    </div>
                    <div className="overflow-x-auto">
                      <table className="min-w-full divide-y divide-[#C8A45D/30]/50">
                        <thead>
                          <tr className="text-left text-[10px] sm:text-xs font-medium text-gray-500 uppercase tracking-wider">
                            <th className="px-2 sm:px-4 py-1 sm:py-2">Stagiaire</th>
                            <th className="px-2 sm:px-4 py-1 sm:py-2">CFF</th>
                            <th className="px-2 sm:px-4 py-1 sm:py-2">Montant</th>
                            <th className="px-2 sm:px-4 py-1 sm:py-2">Date</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-[#C8A45D/30]/30">
