                              <td className="px-2 sm:px-4 py-1 sm:py-2 text-[10px] sm:text-sm">{payment.internName}</td>
                              <td className="px-2 sm:px-4 py-1 sm:py-2 text-[10px] sm:text-sm">{payment.cff}</td>
                              <td className="px-2 sm:px-4 py-1 sm:py-2 text-[10px] sm:text-sm">{payment.amount} DH</td>
                              <td className="px-2 sm:px-4 py-1 sm:py-2 text-[10px] sm:text-sm">{payment.date}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
