                        <div className="flex items-center gap-2 mb-1">
                          <Package className="h-4 w-4 text-[#00717F]" />
                          <h3 className="text-sm font-medium text-[#333333]">Total Produits</h3>
                        </div>
                        <p className="text-2xl font-bold text-[#00717F]">{dashboardData.inventory.products}</p>
                      </div>
                      <div className="bg-orange-50 p-3 rounded-lg">
