                          <AlertCircle className="h-4 w-4 text-orange-600" />
                          <h3 className="text-sm font-medium text-[#333333]">Stock Faible</h3>
                        </div>
                        <p className="text-2xl font-bold text-orange-600">{dashboardData.inventory.lowStock}</p>
                      </div>
                      <div className="bg-red-50 p-3 rounded-lg">
                        <div className="flex items-center gap-2 mb-1">
                          <AlertCircle className="h-4 w-4 text-red-600" />
                          <h3 className="text-sm font-medium text-[#333333]">Expiré</h3>
                        </div>
                        <p className="text-2xl font-bold text-red-600">{dashboardData.inventory.expired}</p>
                      </div>
                    </div>
