                            responsive: true,
                            maintainAspectRatio: false,
                            plugins: { legend: { position: "right" } },
                          }}
                        />
                      </div>
                    </div>
                    <div className="mt-6">
                      <div className="flex justify-between items-center mb-2">
                        <h3 className="text-sm font-medium text-[#333333]">Produits récents</h3>
                        <button
                          onClick={() => navigate("/ManageProducts")}
                          className="text-xs text-[#00717F] hover:text-[#C8A45D] flex items-center gap-1"
