                          Voir tous <ArrowUpRight className="h-3 w-3" />
                        </button>
                      </div>
                      <div className="overflow-x-auto">
                        <table className="min-w-full divide-y divide-[#C8A45D]/30">
                          <thead>
                            <tr className="text-left text-xs font-medium text-[#333333] uppercase tracking-wider">
                              <th className="px-4 py-2">Produit</th>
                              <th className="px-4 py-2">Quantité</th>
                              <th className="px-4 py-2">Prix</th>
                              <th className="px-4 py-2">Expiration</th>
                            </tr>
                          </thead>
                          <tbody className="divide-y divide-[#C8A45D]/20">
                            {dashboardData.inventory.recent.map((product) => (
                              <tr key={product.id} className="hover:bg-[#F5F6FA]/30 transition-colors">
                                <td className="px-4 py-2 text-sm text-[#333333]">{product.name}</td>
                                <td className="px-4 py-2 text-sm text-[#333333]">{product.quantity}</td>
                                <td className="px-4 py-2 text-sm text-[#333333]">{product.price} DH</td>
                                <td className="px-4 py-2 text-sm text-[#333333]">
                                  {new Date() > new Date(product.expiryDate) ? (
                                    <span className="text-red-600">Expiré: {product.expiryDate}</span>
                                  ) : (
                                    product.expiryDate
                                  )}
                                </td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  </div>
                </div>
              </div>

              <div className="space-y-4 sm:space-y-6">
