                        bgColor="bg-[#00717F]/10"
                        onClick={() => navigate("/Interns")}
                      />
                      <DashboardActionButton
                        icon={<Package className="h-5 w-5 sm:h-6 sm:w-6 text-[#C8A45D]" />}
                        label="Stock"
                        bgColor="bg-[#C8A45D]/10"
                        onClick={() => navigate("/ManageProducts")}
                      />
                    </div>
                  </div>
                </div>

                <DashboardSection
                  title="Demandes d'absence"
                  icon={<Calendar className="h-4 w-4 sm:h-5 sm:w-5 text-[#00717F]" />}
