                    <div className="flex justify-between items-center mb-2">
                      <h3 className="text-xs sm:text-sm font-medium text-gray-500">Demandes récentes</h3>
                      <button
                        onClick={() => navigate("/AbsenceRequests")}
                        className="text-[10px] sm:text-xs text-[#00717F] hover:text-[#C8A45D] flex items-center gap-1"
                      >
                        Voir toutes <ChevronRight className="h-2 w-2 sm:h-3 sm:w-3" />
                      </button>
                    </div>
                    <div className="space-y-2">
                      {dashboardData.absences.recent.map((absence) => (
                        <div
                          key={absence.id}
                          className="p-2 sm:p-3 bg-gray-50 rounded-lg hover:bg-[#F5F6FA]/50 transition-colors border border-gray-100"
                        >
                          <div className="flex justify-between items-start">
                            <div>
                              <p className="text-xs sm:text-sm font-medium text-gray-800">{absence.internName}</p>
                              <p className="text-[10px] sm:text-xs text-gray-500">
                                {absence.startDate} - {absence.endDate}
                              </p>
                            </div>
                            <span
                              className={`px-1.5 sm:px-2 py-0.5 text-[10px] sm:text-xs rounded-full ${
                                absence.status === "approved"
                                  ? "bg-green-100 text-green-800"
                                  : absence.status === "rejected"
                                    ? "bg-red-100 text-red-800"
                                    : "bg-[#00717F]/10 text-[#00717F]"
                              }`}
                            >
                              {absence.status === "approved"
                                ? "Approuvée"
                                : absence.status === "rejected"
                                  ? "Rejetée"
                                  : "En attente"}
                            </span>
                          </div>
                          <p className="text-[10px] sm:text-xs text-gray-800 mt-1 line-clamp-1">{absence.reason}</p>
                        </div>
                      ))}
                    </div>
                  </div>
                </DashboardSection>

                <DashboardSection
                  title="Rapports"
                  icon={<FileText className="h-4 w-4 sm:h-5 sm:w-5 text-[#00717F]" />}
                >
                  <div className="flex justify-between items-center mb-2">
                    <h3 className="text-xs sm:text-sm font-medium text-gray-500">Rapports récents</h3>
                    <button
                      onClick={() => navigate("/director/report-history")}
                      className="text-[10px] sm:text-xs text-[#00717F] hover:text-[#C8A45D] flex items-center gap-1"
                    >
                      Voir tous <ChevronRight className="h-2 w-2 sm:h-3 sm:w-3" />
                    </button>
                  </div>
                  <div className="space-y-2">
                    {dashboardData.reports.recent.map((report) => (
                      <div
                        key={report.id}
                        className="p-2 sm:p-3 bg-gray-50 rounded-lg hover:bg-[#F5F6FA]/50 transition-colors border border-gray-100"
                      >
                        <div className="flex justify-between items-start">
                          <div>
                            <p className="text-xs sm:text-sm font-medium text-gray-800">
                              {report.type === "réclamation" ? "Réclamation" : "Remarque"}
                            </p>
                            <p className="text-[10px] sm:text-xs text-gray-500">{report.date}</p>
                          </div>
                          <span
                            className={`px-1.5 sm:px-2 py-0.5 text-[10px] sm:text-xs rounded-full ${
                              report.type === "réclamation"
                                ? "bg-red-100 text-red-800"
                                : "bg-[#00717F]/10 text-[#00717F]"
                            }`}
                          >
                            {report.type === "réclamation" ? "Réclamation" : "Remarque"}
                          </span>
                        </div>
                        <p className="text-[10px] sm:text-xs text-gray-800 mt-1 line-clamp-2">{report.description}</p>
                      </div>
                    ))}
                  </div>
                </DashboardSection>
              </div>
            </div>
          </>
        )}
      </div>
    </Layout>
  )
}
